const GENS = [
  gx('pr-g01', 3, 'nat', 'oxalic acid and KMnO4', (rng) => {
    const Mox = pick(rng, 0.04, 0.1, 0.01), Vox = pick(rng, 10, 25, 5), V = pick(rng, 10, 30, 2.5); const M = 0.4 * Mox * Vox / V;
    return { q: `${Vox} mL of ${Mox} M oxalic acid is titrated against KMnO<sub>4</sub> in dilute H<sub>2</sub>SO<sub>4</sub> at about 333 K and needs ${V} mL of the permanganate. Find the molarity of KMnO<sub>4</sub>.`, answer: +M.toFixed(4), tol: Math.max(0.0002, M * 0.01), unit: 'M', Mox, Vox, V,
      sol: `<p>2MnO<sub>4</sub><sup>&minus;</sup> + 5H<sub>2</sub>C<sub>2</sub>O<sub>4</sub>: moles of KMnO<sub>4</sub> = (2/5) &times; ${Mox} &times; ${Vox} = ${fmt(0.4 * Mox * Vox, 4)} mmol.</p><p>M = ${fmt(0.4 * Mox * Vox, 4)}/${V} = <b>${M.toFixed(4)} M</b>.</p>`, trap: 'The ratio is 2 : 5, not 1 : 1.' };
  }, (p) => (2 * p.Mox * p.Vox) / (5 * p.V)),
  gx('pr-g02', 3, 'nat', 'Mohr salt and KMnO4', (rng) => {
    const M = pick(rng, 0.04, 0.1, 0.01), Vm = pick(rng, 10, 30, 5), Vk = pick(rng, 10, 30, 2.5); const c = M * Vm / (5 * Vk);
    return { q: `${Vm} mL of ${M} M Mohr's salt solution in dilute H<sub>2</sub>SO<sub>4</sub> is titrated with KMnO<sub>4</sub> at room temperature, needing ${Vk} mL. Find the molarity of the KMnO<sub>4</sub>.`, answer: +c.toFixed(4), tol: Math.max(0.0002, c * 0.01), unit: 'M', M, Vm, Vk,
      sol: `<p>5Fe<sup>2+</sup> + MnO<sub>4</sub><sup>&minus;</sup> + 8H<sup>+</sup> &rarr; 5Fe<sup>3+</sup> + Mn<sup>2+</sup> + 4H<sub>2</sub>O. Fe<sup>2+</sup> = ${fmt(M * Vm, 4)} mmol, so KMnO<sub>4</sub> = ${fmt(M * Vm / 5, 4)} mmol.</p><p>M = ${fmt(M * Vm / 5, 4)}/${Vk} = <b>${c.toFixed(4)} M</b>.</p>`, trap: 'Five Fe<sup>2+</sup> per MnO<sub>4</sub><sup>&minus;</sup>.' };
  }, (p) => p.M * p.Vm / 5 / p.Vk),
  gx('pr-g03', 2, 'nat', 'mass for a standard solution', (rng) => {
    const V = choose(rng, [100, 250, 500]); const kind = choose(rng, [['oxalic acid dihydrate', 126, 2, 'H<sub>2</sub>C<sub>2</sub>O<sub>4</sub>&middot;2H<sub>2</sub>O'], ['Mohr\'s salt', 392, 1, 'FeSO<sub>4</sub>&middot;(NH<sub>4</sub>)<sub>2</sub>SO<sub>4</sub>&middot;6H<sub>2</sub>O']]); const N = choose(rng, [0.05, 0.1]); const M = N / kind[2]; const m = M * V / 1000 * kind[1];
    return { q: `What mass of ${kind[0]} (${kind[3]}, ${kind[1]} g/mol) is needed to make ${V} mL of ${N} N solution (for use with KMnO<sub>4</sub> or NaOH)?`, answer: +m.toFixed(3), tol: Math.max(0.005, m * 0.005), unit: 'g', V, N, e: kind[2], mm: kind[1],
      sol: `<p>${kind[2] === 2 ? 'Oxalic acid is dibasic (2 electrons), so M = N/2' : 'Mohr\'s salt gives 1 electron per Fe<sup>2+</sup>, so M = N'} = ${M}.</p><p>Mass = ${M} &times; ${V}/1000 &times; ${kind[1]} = <b>${m.toFixed(3)} g</b>.</p>`, trap: 'Convert normality to molarity first.' };
  }, (p) => p.N / p.e * p.V / 1000 * p.mm),
  gx('pr-g04', 2, 'nat', 'acid-base titration', (rng) => {
    const Ma = pick(rng, 0.05, 0.2, 0.05), Va = pick(rng, 10, 25, 5), Vb = pick(rng, 10, 25, 5); const dib = rng() < 0.4; const Mb = (dib ? 2 : 1) * Ma * Va / Vb;
    return { q: `${Va} mL of ${Ma} M ${dib ? 'oxalic acid (dibasic)' : 'HCl'} is neutralised by ${Vb} mL of NaOH solution. Find the molarity of NaOH.`, answer: +Mb.toFixed(4), tol: Math.max(0.001, Mb * 0.01), unit: 'M', Ma, Va, Vb, dib,
      sol: `<p>Moles of H<sup>+</sup> = ${dib ? '2 &times; ' : ''}${Ma} &times; ${Va} = ${fmt((dib ? 2 : 1) * Ma * Va, 4)} mmol = moles of OH<sup>&minus;</sup>.</p><p>M(NaOH) = ${fmt((dib ? 2 : 1) * Ma * Va, 4)}/${Vb} = <b>${Mb.toFixed(4)} M</b>.</p>`, trap: 'A dibasic acid supplies two H<sup>+</sup>.' };
  }, (p) => (p.dib ? 2 : 1) * p.Ma * p.Va / p.Vb),
  gx('pr-g05', 3, 'nat', 'volume of KMnO4 needed', (rng) => {
    const M = pick(rng, 0.05, 0.1, 0.01), V = pick(rng, 10, 25, 5), c = pick(rng, 0.02, 0.04, 0.01); const acid = rng() < 0.5;
    const need = acid ? 0.4 * M * V / c : M * V / (5 * c);
    return { q: `What volume of ${c} M KMnO<sub>4</sub> (acidified) is needed to react completely with ${V} mL of ${M} M ${acid ? 'oxalic acid' : 'Mohr\'s salt (Fe<sup>2+</sup>)'}?`, answer: +need.toFixed(2), tol: Math.max(0.05, need * 0.01), unit: 'mL', M, V, c, acid,
      sol: `<p>${acid ? 'Ratio 2 MnO<sub>4</sub><sup>&minus;</sup> : 5 oxalic acid, so mmol of KMnO<sub>4</sub> = 0.4 &times; ' + M + ' &times; ' + V : 'Ratio 1 MnO<sub>4</sub><sup>&minus;</sup> : 5 Fe<sup>2+</sup>, so mmol of KMnO<sub>4</sub> = ' + M + ' &times; ' + V + '/5'} = ${fmt(acid ? 0.4 * M * V : M * V / 5, 4)}.</p><p>V = ${fmt(acid ? 0.4 * M * V : M * V / 5, 4)}/${c} = <b>${need.toFixed(2)} mL</b>.</p>` };
  }, (p) => (p.acid ? 2 * p.M * p.V / 5 : p.M * p.V / 5) / p.c),
  gx('pr-g06', 2, 'nat', 'Rf value', (rng) => {
    const f = pick(rng, 5, 12, 0.5), r = pick(rng, 0.15, 0.85, 0.05); const d = +(f * r).toFixed(2);
    return { q: `The solvent front travels ${f} cm. A spot is at ${d} cm from the origin. Find its R<sub>f</sub> value.`, answer: +(d / f).toFixed(3), tol: 0.005, f, d,
      sol: `<p>R<sub>f</sub> = ${d}/${f} = <b>${(d / f).toFixed(2)}</b>.</p>`, trap: 'Measure both from the origin line, not the paper edge.' };
  }, (p) => p.d / p.f),
  gx('pr-g07', 3, 'nat', 'distance moved on a chromatogram', (rng) => {
    const f = pick(rng, 6, 14, 1), r = pick(rng, 0.2, 0.9, 0.05); const d = f * r;
    return { q: `A compound has R<sub>f</sub> = ${r} in a solvent. When the solvent front has travelled ${f} cm from the origin, how far has the compound moved, in cm?`, answer: +d.toFixed(2), tol: 0.02, unit: 'cm', r, f,
      sol: `<p>Distance = R<sub>f</sub> &times; distance of the solvent front = ${r} &times; ${f} = <b>${d.toFixed(2)} cm</b>.</p>` };
  }, (p) => p.f * p.r),
  gx('pr-g08', 3, 'nat', 'percentage yield', (rng) => {
    const [nm, M1, M2, reag] = choose(rng, SOLID); const n = choose(rng, [0.02, 0.05, 0.1]); const y = pick(rng, 55, 90, 5); const m1 = +(n * M1).toFixed(2); const th = n * M2; const act = +(th * y / 100).toFixed(2);
    return { q: `${m1} g of ${reag} (${M1} g/mol) gives ${act} g of ${nm} (${M2} g/mol) in a preparation. Find the percentage yield.`, answer: +(act / th * 100).toFixed(1), tol: 0.3, unit: '%', m1, M1, M2, act,
      sol: `<p>Moles = ${m1}/${M1} = ${n}. Theoretical ${nm} = ${n} &times; ${M2} = ${fmt(th, 4)} g (one mole of product per mole of reactant).</p><p>Yield = ${act}/${fmt(th, 4)} &times; 100 = <b>${(act / th * 100).toFixed(1)} %</b>.</p>` };
  }, (p) => p.act / (p.m1 / p.M1 * p.M2) * 100),
  gx('pr-g09', 3, 'nat', 'iodoform yield', (rng) => {
    const [nm, M] = choose(rng, [['acetone', 58], ['ethanol', 46]]); const n = choose(rng, [0.05, 0.1, 0.2]); const m = +(n * M).toFixed(2); const th = n * 394;
    return { q: `${m} g of ${nm} (${M} g/mol) is converted into iodoform (CHI<sub>3</sub>, 394 g/mol) by warming with I<sub>2</sub> and NaOH. Find the theoretical yield, in grams.`, answer: +th.toFixed(2), tol: Math.max(0.05, th * 0.005), unit: 'g', m, M,
      sol: `<p>One mole of ${nm} gives one mole of iodoform. Moles = ${m}/${M} = ${n}.</p><p>Mass = ${n} &times; 394 = <b>${th.toFixed(2)} g</b>.</p>`, trap: 'Ethanol is first oxidised to ethanal, but the carbon count still gives 1 : 1.' };
  }, (p) => p.m / p.M * 394),
  gx('pr-g10', 3, 'nat', 'equivalent mass of KMnO4', (rng) => {
    const [medium, n] = choose(rng, [['acidic', 5], ['neutral (to MnO<sub>2</sub>)', 3], ['strongly alkaline (to MnO<sub>4</sub><sup>2&minus;</sup>)', 1]]); const e = 158 / n;
    return { q: `Find the equivalent mass of KMnO<sub>4</sub> (158 g/mol) in ${medium} medium.`, answer: +e.toFixed(2), tol: 0.05, unit: 'g/eq', n,
      sol: `<p>Equivalent mass = molar mass / electrons gained per molecule = 158/${n} = <b>${e.toFixed(2)}</b>.</p>` };
  }, (p) => 158 / p.n),
  gx('pr-g11', 4, 'nat', 'purity from titration', (rng) => {
    const m = pick(rng, 3, 5, 0.5), pure = pick(rng, 70, 95, 5); const mm = m * pure / 100; const molFe = mm / 392 * 1000; const Vk = +(molFe / 5 / 0.1).toFixed(1); const p = 5 * 0.1 * Vk * 392 / 1000 / m * 100;
    return { q: `${m} g of impure Mohr's salt is dissolved in dilute H<sub>2</sub>SO<sub>4</sub> and needs ${Vk} mL of 0.1 M KMnO<sub>4</sub>. Find the percentage purity (Mohr's salt = 392 g/mol; assume the whole sample is titrated).`, answer: +p.toFixed(1), tol: 0.3, unit: '%', m, Vk,
      sol: `<p>KMnO<sub>4</sub> = 0.1 &times; ${Vk} = ${(0.1 * Vk).toFixed(2)} mmol. Fe<sup>2+</sup> = 5 &times; that = ${(0.5 * Vk).toFixed(2)} mmol, so Mohr's salt = ${(0.5 * Vk * 392 / 1000).toFixed(3)} g.</p><p>Purity = ${(0.5 * Vk * 392 / 1000).toFixed(3)}/${m} &times; 100 = <b>${p.toFixed(1)} %</b>.</p>`, trap: 'Five Fe<sup>2+</sup> per permanganate.' };
  }, (p) => 5 * 0.1 * p.Vk * 392 / 1000 / p.m * 100),
  gx('pr-g12', 1, 'mcq', 'anion tests', (rng) => {
    const [an, t] = choose(rng, ANION); const ws = ANION.filter((x) => x[0] !== an).map((x) => x[1]).sort(() => rng() - 0.5).slice(0, 3); const { options, answer } = shuffleOpts(rng, t, ws);
    return { q: `The test for the ${an} ion is`, options, answer, t, sol: `<p>${an[0].toUpperCase() + an.slice(1)}: <b>${t}</b>.</p>`, trap: 'Learn the observation with the reagent.' };
  }, (p) => p.options.indexOf(p.t)),
  gx('pr-g13', 1, 'mcq', 'flame tests', (rng) => {
    const [c, f] = choose(rng, FLAME); const ws = FLAME.filter((x) => x[1] !== f).map((x) => x[1]).sort(() => rng() - 0.5).slice(0, 3); const { options, answer } = shuffleOpts(rng, f, ws);
    return { q: `The flame colour given by ${c} is`, options, answer, f, sol: `<p>${c}: <b>${f}</b>.</p>` };
  }, (p) => p.options.indexOf(p.f)),
  gx('pr-g14', 2, 'mcq', 'cation groups', (rng) => {
    const [c, g] = choose(rng, GROUPS); const all = ['I', 'II', 'III', 'IV', 'V', 'VI']; const ws = all.filter((x) => x !== g).sort(() => rng() - 0.5).slice(0, 3).map((x) => `Group ${x}`); const { options, answer } = shuffleOpts(rng, `Group ${g}`, ws);
    return { q: `In the systematic analysis of cations, ${c} is precipitated in`, options, answer, g, sol: `<p>${c} belongs to <b>Group ${g}</b>. Group I: dilute HCl; II: H<sub>2</sub>S in dilute HCl; III: NH<sub>4</sub>OH with NH<sub>4</sub>Cl; IV: H<sub>2</sub>S in ammoniacal medium; V: (NH<sub>4</sub>)<sub>2</sub>CO<sub>3</sub>; VI: Mg<sup>2+</sup> (Na<sub>2</sub>HPO<sub>4</sub>).</p>`, trap: 'Know the group reagent for each group.' };
  }, (p) => p.options.indexOf(`Group ${p.g}`)),
  gx('pr-g15', 2, 'mcq', 'choice of indicator', (rng) => {
    const [pair, ind] = choose(rng, TITR); const ws = INDS.filter((x) => x !== ind).sort(() => rng() - 0.5).slice(0, 3); const { options, answer } = shuffleOpts(rng, ind, ws);
    return { q: `The suitable indicator for the titration of ${pair} is`, options, answer, ind, sol: `<p>For <b>${ind}</b>: the end point pH of this titration fits its range (weak acid with strong base is basic, so phenolphthalein; strong acid with weak base is acidic, so methyl orange).</p>`, trap: 'Match the indicator range to the pH at the equivalence point.' };
  }, (p) => p.options.indexOf(p.ind)),
  gx('pr-g16', 2, 'mcq', 'Lassaigne test', (rng) => {
    const [el, t] = choose(rng, LASS); const ws = LASS.filter((x) => x[0] !== el).map((x) => x[1]).sort(() => rng() - 0.5).slice(0, 3); const { options, answer } = shuffleOpts(rng, t, ws);
    return { q: `In the Lassaigne test, ${el} is shown by a`, options, answer, t, sol: `<p>${el[0].toUpperCase() + el.slice(1)}: <b>${t}</b>.</p>` };
  }, (p) => p.options.indexOf(p.t)),
  gx('pr-g17', 2, 'mcq', 'functional group tests', (rng) => {
    const [g, t] = choose(rng, FGT); const ws = FGT.filter((x) => x[0] !== g).map((x) => x[1]).sort(() => rng() - 0.5).slice(0, 3); const { options, answer } = shuffleOpts(rng, t, ws);
    return { q: `A compound that is ${g} is expected to show`, options, answer, t, sol: `<p>${g[0].toUpperCase() + g.slice(1)}: <b>${t}</b>.</p>` };
  }, (p) => p.options.indexOf(p.t)),
];

export default {
  topic: 'practical-chemistry',
  groups: GRP,
  items: FIXED,
  gens: GENS,
};
